@import url('https://fonts.googleapis.com/css2?family=Anton&family=Manrope:wght@400;500;600;700&display=swap');
/* Wreck the Room checkout: dark page, light card. Pasted into each offer's checkout theme (Settings → CSS). */
html,body,body.background-light,main,main>div,main .section,main .sizer{background-color:#0a0908 !important;}
body{background-image:radial-gradient(ellipse at 50% -10%,rgba(201,168,76,.16),transparent 55%) !important;background-attachment:fixed !important;}
.section .sizer{padding-top:24px !important;padding-bottom:70px !important;}
.checkout-standalone-column{flex:0 0 100% !important;max-width:1060px !important;}

/* brand bar + steps (added by the checkout script) */
.wtr-co-top{max-width:1060px;margin:0 auto 26px;font-family:Manrope,system-ui,sans-serif;color:#d2cbbe;}
.wtr-co-bar{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:10px 0 26px;border-bottom:1px solid rgba(201,168,76,.22);}
.wtr-co-bar img{width:140px;height:auto;display:block;}
.wtr-co-lock{display:flex;align-items:center;gap:8px;font-size:11px;font-weight:700;letter-spacing:.2em;text-transform:uppercase;color:#ecd69b;}
.wtr-co-lock svg{width:14px;height:14px;fill:none;stroke:currentColor;stroke-width:2;}
.wtr-co-head{text-align:center;margin:40px 0 28px;}
.wtr-co-head small{display:block;font-size:11px;font-weight:700;letter-spacing:.3em;text-transform:uppercase;color:#c9a84c;margin-bottom:12px;}
.wtr-co-head h1{margin:0;font-family:Anton,Impact,sans-serif;font-weight:400;text-transform:uppercase;letter-spacing:.01em;font-size:clamp(34px,4.6vw,58px);line-height:1.02;color:#f3ede2 !important;}
.wtr-co-head h1 em{font-style:normal;color:#d8483b;}
.wtr-co-steps{list-style:none;margin:0 auto;padding:0;display:flex;justify-content:center;gap:12px 34px;flex-wrap:wrap;}
.wtr-co-steps li{display:flex;align-items:center;gap:10px;font-size:14px;font-weight:600;color:#f3ede2;}
.wtr-co-steps b{display:inline-flex;align-items:center;justify-content:center;width:26px;height:26px;border-radius:50%;background:linear-gradient(135deg,#ecd69b,#c9a84c 55%,#8c7231);color:#0b0a08;font-size:12px;font-weight:700;}

/* the card */
.embedded-checkout{font-family:Manrope,system-ui,sans-serif !important;border:1px solid #c9a84c !important;border-radius:4px !important;overflow:hidden;box-shadow:0 30px 80px rgba(0,0,0,.55) !important;background:#fbf8f2 !important;}
.embedded-checkout__body{background:#fbf8f2 !important;}
.embedded-checkout__summary{background:#f1ebde !important;}
.embedded-checkout__form{background:#fbf8f2 !important;}
.embedded-checkout,.embedded-checkout *:not(#offer-title):not(#offer-price){font-family:Manrope,system-ui,sans-serif !important;}
.embedded-checkout{--pine-font-family:Manrope,system-ui,sans-serif;--pine-typography-body-font-family:Manrope,system-ui,sans-serif;--sage-font-family:Manrope,system-ui,sans-serif;}
main .section__overlay{display:none !important;}
.embedded-checkout__legend,.embedded-checkout-pricing-options-title{font-size:11px !important;font-weight:700 !important;letter-spacing:.22em !important;text-transform:uppercase !important;color:#8c7231 !important;}
#offer-title{font-family:Anton,Impact,sans-serif !important;font-weight:400 !important;text-transform:uppercase;font-size:28px !important;line-height:1.08 !important;color:#14110c !important;letter-spacing:.01em;}
#offer-price{font-family:Anton,Impact,sans-serif !important;font-weight:400 !important;font-size:40px !important;color:#14110c !important;}
.embedded-checkout .t-sage-heading-4{color:#14110c !important;}
.embedded-checkout .sage-badge{background:#e8dfcb !important;border-color:#d8cbae !important;}
.embedded-checkout .sage-badge__value-text{color:#5b4a1f !important;}
.embedded-checkout-price-display__image,.order-bump__thumbnail img{border-radius:3px !important;}
.embedded-checkout-pricing-option{border-radius:4px !important;border-color:#d8cbae !important;background:#fff !important;cursor:pointer;transition:border-color .2s,box-shadow .2s;}
.embedded-checkout-pricing-option:hover{border-color:#c9a84c !important;}
.embedded-checkout-pricing-option.selected{border-color:#b08d3c !important;box-shadow:0 0 0 2px rgba(201,168,76,.35) !important;}
.embedded-checkout .embedded-checkout-pricing-option p.description{color:#14110c !important;font-size:15px !important;font-weight:600 !important;}
.embedded-checkout .offer-summary,.embedded-checkout .offer-summary pds-text,.embedded-checkout .embedded-checkout-price-detail,.embedded-checkout .embedded-checkout-price-detail *{color:#14110c !important;}
.recommendation-header,.recommendation-header *{background:#14110c !important;color:#ecd69b !important;font-size:11px !important;font-weight:700 !important;letter-spacing:.2em !important;text-transform:uppercase !important;}
.pricing-option-indicator.selected{background-color:#b08d3c !important;border-color:#b08d3c !important;}
.embedded-checkout input.sage-input__field,.embedded-checkout .sage-form-field{border-radius:3px !important;border-color:#d8cbae !important;background:#fff !important;}
.embedded-checkout input:focus{border-color:#b08d3c !important;box-shadow:0 0 0 3px rgba(201,168,76,.25) !important;}
.embedded-checkout .sage-checkbox__label{color:#2a241a !important;font-size:14px !important;}
.embedded-checkout .sage-checkbox__input:checked{background-color:#b08d3c !important;border-color:#b08d3c !important;}
.embedded-checkout-coupon__button-wrapper .sage-btn{background:#14110c !important;color:#ecd69b !important;border-radius:3px !important;}

/* pay button */
.embedded-checkout__cta button[type=submit]{min-height:58px !important;border:0 !important;border-radius:3px !important;background:linear-gradient(135deg,#ecd69b,#c9a84c 55%,#a5862f) !important;color:#0b0a08 !important;font-size:15px !important;font-weight:700 !important;letter-spacing:.14em !important;text-transform:uppercase !important;box-shadow:0 10px 26px rgba(201,168,76,.35) !important;transition:transform .2s,box-shadow .2s !important;}
.embedded-checkout__cta button[type=submit]:hover{transform:translateY(-1px);box-shadow:0 14px 32px rgba(201,168,76,.45) !important;}
.embedded-checkout__cta button[type=submit] *{color:#0b0a08 !important;}

/* terms: a short box that opens on request */
.service-agreement-text{position:relative;max-height:96px !important;overflow:hidden !important;padding:14px 16px !important;border:1px solid #e3d9c3 !important;border-radius:3px !important;background:#f6f1e6 !important;font-size:12.5px !important;line-height:1.55 !important;color:#4a4232 !important;transition:max-height .35s;}
.service-agreement-text *{font-size:12.5px !important;line-height:1.55 !important;margin:0 0 8px !important;color:#4a4232 !important;font-family:Manrope,system-ui,sans-serif !important;}
.service-agreement-text h1,.service-agreement-text h2,.service-agreement-text h3,.service-agreement-text h4{font-weight:700 !important;letter-spacing:.06em !important;text-transform:uppercase;color:#14110c !important;}
.service-agreement-text::after{content:"";position:absolute;left:0;right:0;bottom:32px;height:34px;background:linear-gradient(0deg,#f6f1e6,rgba(246,241,230,0));pointer-events:none;}
.service-agreement-text.wtr-open{max-height:340px !important;overflow:auto !important;}
.service-agreement-text.wtr-open::after{display:none;}
.service-agreement-text{cursor:pointer;padding-bottom:44px !important;}
.service-agreement-text.wtr-open{cursor:auto;padding-bottom:14px !important;}
.service-agreement-text::before{content:"Read full terms \25BE";position:absolute;left:0;right:0;bottom:0;z-index:2;padding:10px 16px;background:#f6f1e6;border-top:1px solid #e3d9c3;font:700 11px/1 Manrope,system-ui,sans-serif;letter-spacing:.12em;text-transform:uppercase;color:#8c7231;}
.service-agreement-text.wtr-open::before{display:none;}

/* reassurance under the pay button */
.embedded-checkout__cta::after{content:"\1F512  Secure checkout   \00B7   \2713  Instant access by email";white-space:pre;display:block;text-align:center;font:600 12.5px/1.4 Manrope,system-ui,sans-serif;color:#4a4232;margin-top:-4px;}
.embedded-checkout__footer{background:#14110c !important;border-top:0 !important;}
.embedded-checkout__footer,.embedded-checkout__footer *{color:#d2cbbe !important;font-size:12px !important;letter-spacing:.06em;}

@media (max-width:767px){
  .section .sizer{padding-top:8px !important;padding-bottom:40px !important;}
  .container{padding-left:14px !important;padding-right:14px !important;}
  .wtr-co-bar img{width:112px;}
  .wtr-co-lock{font-size:10px;letter-spacing:.14em;}
  .wtr-co-head{margin:26px 0 20px;}
  .wtr-co-steps{flex-direction:column;align-items:flex-start;max-width:290px;gap:10px;}
  #offer-title{font-size:22px !important;}
  #offer-price{font-size:32px !important;}
}

